-- Icecrown: creature abilities
-- Most of the zone's creatures (the Scourge, the Cult of the Damned, the vrykul and the Argent Crusade's foes) had no AI or ran
-- classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows needing events,
-- actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The creatures no reference
-- scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '29333,29392,29489,29490,29648,29719,29720,29722,29738,29769,29770,29840,30409,30689,30703,30704,30746,30922,30949,30993,31015,31016,31049,31137,31150,31198,31255,31265,31277,31280,31283,31314,31316,31320,31321,31322,31397,31701,31702,31731,31747,31812,31813,31815,31832,31843,32149,32154,32162,32163,32175,32176,32260,32262,32267,32278,32280,32284,32299,32479,32482,32492,32502,32505,32767,32769,33429,33785';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '29517,30188,30189,30205,30206,30312,30333,30482,30541,30544,30575,30633,30672,30673,30674,30751,30957,30958,30988,31039,31040,31042,31043,31226,31250,31263,31266,31318,31325,31399,31414,31435,31438,31554,31721,31780,31853,32164,32188,32468,32488,32503,34179,35072,38505';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
